import os,json,requests,sys,pathlib,base64,gzip
key=os.getenv('OPENROUTER_API_KEY')
if not key: print('OPENROUTER_API_KEY not configured; semantic reviewer skipped. Deterministic gate remains blocking.'); raise SystemExit(0)
b=''.join(pathlib.Path(f'data-v2/chunks/course-part-{i:02}.b64').read_text().strip() for i in range(27)); raw=json.loads(gzip.decompress(base64.b64decode(b))); summary=[{'school':s['title'],'lessons':[{'id':l['id'],'title':l['title'],'summary':l['summary'],'mechanism':l['core'],'diagnostic':l['observe'],'break':l['breakIt'],'measure':l['measure'],'lab':{'mode':l['lab']['mode'],'language':l['lab']['language']}} for l in s['lessons']]} for s in raw['schools']]
prompt='Act as a principal AI engineer and demanding curriculum reviewer. Audit conceptual holes, generic filler, duplicated pedagogy, unsafe advice, false mastery, weak/non-causal labs, missing eval/security/production concepts. Return strict JSON {"pass":boolean,"score":0-100,"blocking":[],"major":[],"strengths":[],"next_improvement":string}. Pass only >=90 and zero blockers. Curriculum:\n'+json.dumps(summary)
r=requests.post('https://openrouter.ai/api/v1/chat/completions',headers={'Authorization':f'Bearer {key}','Content-Type':'application/json','X-Title':'AI Engineering Mastery CI'},json={'model':'stealth/ox-alpha','messages':[{'role':'user','content':prompt}],'temperature':0.1},timeout=180);r.raise_for_status();out=r.json()['choices'][0]['message']['content'];print(out);obj=json.loads(out.strip().removeprefix('```json').removesuffix('```').strip());sys.exit(0 if obj.get('pass') and obj.get('score',0)>=90 and not obj.get('blocking') else 1)
